  "inlineSchema": "// Este es el archivo \"schema\" de Prisma.\n// Define la conexión a tu base de datos y la estructura de tus tablas.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// --- ENUMS (Tipos predefinidos) ---\n\nenum Role {\n  USER\n  ADMIN\n}\n\nenum TransactionStatus {\n  INICIADO\n  PAGADO_EN_RETENCION\n  COMPLETADO\n  DISPUTADO\n  CANCELADO\n}\n\n// ¡NUEVO! Tipología de la Publicación (Para diferenciar lógica de envío/entrega)\nenum ListingType {\n  PRODUCTO // Bien físico (Requiere envío/logística)\n  SERVICIO // Intangible (Requiere coordinación/agenda)\n  INFOPRODUCTO // Digital (Requiere link de descarga o acceso)\n}\n\n// --- MODELOS DE DATOS ---\n\n// 1. Modelo de CATEGORÍAS (Estructura de Árbol)\nmodel Category {\n  id   String @id @default(uuid())\n  name String\n  slug String @unique // Para URLs amigables (ej: \"tecnologia-celulares\")\n\n  // Relación Recursiva (Categoría Padre e Hijas)\n  parentId String? // Puede ser null si es una Categoría Principal\n  parent   Category?  @relation(\"SubCategories\", fields: [parentId], references: [id])\n  children Category[] @relation(\"SubCategories\")\n\n  // Relación con Productos\n  products Product[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// 2. Modelo de USUARIO\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String\n  name      String?\n  role      Role     @default(USER)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  products             Product[]\n  services             Service[] // (Legacy) Mantener por compatibilidad temporal\n  transactionsAsBuyer  Transaction[]        @relation(\"BuyerTransactions\")\n  transactionsAsSeller Transaction[]        @relation(\"SellerTransactions\")\n  ratingsGiven         Rating[]             @relation(\"RaterRatings\")\n  ratingsReceived      Rating[]             @relation(\"RatedRatings\")\n  professionalProfile  ProfessionalProfile?\n}\n\n// 3. Modelo de PERFIL PROFESIONAL\nmodel ProfessionalProfile {\n  id              String   @id @default(uuid())\n  user            User     @relation(fields: [userId], references: [id])\n  userId          String   @unique\n  title           String?\n  experienceYears Int?\n  education       String?\n  summary         String?  @db.Text\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\n// 4. Modelo de PRODUCTO (Ahora es la entidad central \"Publicación\")\nmodel Product {\n  id        String @id @default(uuid())\n  creator   User   @relation(fields: [creatorId], references: [id])\n  creatorId String\n\n  // ¡NUEVO! Clasificación y Tipología\n  category   Category?   @relation(fields: [categoryId], references: [id])\n  categoryId String? // Opcional temporalmente para no romper productos viejos\n  type       ListingType @default(PRODUCTO) // Por defecto es físico\n\n  title       String\n  description String   @db.Text\n  price       Float\n  images      String[]\n  status      String   @default(\"DISPONIBLE\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  transactions Transaction[]\n}\n\n// 5. Modelo de SERVICIO (LEGACY / DEPRECATED)\n// NOTA DE ARQUITECTURA: A futuro, los servicios deben migrarse a la tabla Product\n// con type=\"SERVICIO\". Mantenemos esta tabla para no romper lógica existente hoy.\nmodel Service {\n  id              String   @id @default(uuid())\n  creator         User     @relation(fields: [creatorId], references: [id])\n  creatorId       String\n  title           String\n  description     String   @db.Text\n  price           Float\n  status          String   @default(\"DISPONIBLE\")\n  timesContracted Int      @default(0)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  transactions Transaction[]\n}\n\n// 6. Modelo de TRANSACCIÓN\nmodel Transaction {\n  id       String @id @default(uuid())\n  buyer    User   @relation(\"BuyerTransactions\", fields: [buyerId], references: [id])\n  buyerId  String\n  seller   User   @relation(\"SellerTransactions\", fields: [sellerId], references: [id])\n  sellerId String\n\n  // Relación con Items (Soporta el modelo nuevo y el viejo)\n  product   Product? @relation(fields: [productId], references: [id])\n  productId String?\n  service   Service? @relation(fields: [serviceId], references: [id])\n  serviceId String?\n\n  status        TransactionStatus @default(INICIADO)\n  amount        Float\n  platformFee   Float\n  sellerPayout  Float\n  mercadoPagoId String?           @unique\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  rating Rating?\n}\n\n// 7. Modelo de CALIFICACIÓN\nmodel Rating {\n  id            String      @id @default(uuid())\n  transaction   Transaction @relation(fields: [transactionId], references: [id])\n  transactionId String      @unique\n\n  rater   User   @relation(\"RaterRatings\", fields: [raterId], references: [id])\n  raterId String\n  rated   User   @relation(\"RatedRatings\", fields: [ratedId], references: [id])\n  ratedId String\n\n  rating  Int\n  comment String? @db.Text\n\n  quality         Int?\n  professionalism Int?\n  communication   Int?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n",
